// Task defines model for Task.
type Task struct {
	// AreaId The area path this item belongs to (same project).
	AreaId *openapi_types.UUID `json:"areaId"`

	// AssigneeIds People assigned to this task. Empty array means unassigned.
	AssigneeIds []openapi_types.UUID `json:"assigneeIds"`

	// Assignments Each assignee's share of the task's man-days.
	Assignments []TaskAssignment `json:"assignments"`

	// BlockedByIds Tasks that must be finished before this one can be (same project). Sorted by task number.
	BlockedByIds []openapi_types.UUID `json:"blockedByIds"`
	CompletedAt  *time.Time           `json:"completedAt"`

	// CompletedManDays Work done so far, in man-days (0–9999).
	CompletedManDays *float64  `json:"completedManDays"`
	CreatedAt        time.Time `json:"createdAt"`

	// CustomType One of the project's own types (key); type is then its base.
	CustomType      *string            `json:"customType"`
	CustomTypeColor *WorkItemTypeColor `json:"customTypeColor"`
	CustomTypeLabel *string            `json:"customTypeLabel"`

	// CustomValues Values of the project's custom fields, by key (text, number or YYYY-MM-DD; a select's option).
	CustomValues map[string]any      `json:"customValues"`
	Description  *string             `json:"description"`
	DueDate      *openapi_types.Date `json:"dueDate"`

	// DuplicateOfId The task this one is a copy of (same project).
	DuplicateOfId *openapi_types.UUID `json:"duplicateOfId"`

	// EstimateManDays The task's man-day size as entered on the task itself, before (or without) splitting it across assignees.
	EstimateManDays *float64           `json:"estimateManDays"`
	Id              openapi_types.UUID `json:"id"`

	// ManDays Total man-days: the sum of assignments when they carry any man-days, otherwise estimateManDays (0 when neither). Computed server-side.
	ManDays     float64             `json:"manDays"`
	MilestoneId *openapi_types.UUID `json:"milestoneId"`

	// Number Per-project sequential number, e.g. 42 for "PYR-42".
	Number int `json:"number"`

	// ParentId The work item this one sits under (same project, up to 5 levels, never a loop, never under a lower-level type). A task that has subtasks doesn't count its own man-days toward capacity; its subtasks carry the work.
	ParentId  *openapi_types.UUID `json:"parentId"`
	Priority  TaskPriority        `json:"priority"`
	ProjectId openapi_types.UUID  `json:"projectId"`

	// Rank Manual order within the project, lower first. Change it with POST /tasks/{id}/move.
	Rank float64 `json:"rank"`

	// RelatedIds Tasks linked as related (both ways, same project), by task number.
	RelatedIds []openapi_types.UUID `json:"relatedIds"`

	// RemainingManDays Work left, in man-days (0–9999). Set to 0 when the item is done.
	RemainingManDays *float64 `json:"remainingManDays"`

	// SprintId The sprint this item is planned in (same project).
	SprintId *openapi_types.UUID `json:"sprintId"`

	// StartDate Planned start; man-days are spread over the working days from startDate to dueDate.
	StartDate *openapi_types.Date `json:"startDate"`

	// State The item's state in its project's workflow; status is that state's category.
	State  string     `json:"state"`
	Status TaskStatus `json:"status"`

	// StoryPoints Relative size in points (0–999).
	StoryPoints *float64 `json:"storyPoints"`

	// Tags The task's tags, sorted alphabetically (case-insensitive). Tags are shared across all projects.
	Tags  []string `json:"tags"`
	Title string   `json:"title"`

	// Type Work item type. Levels from top: epic, feature, story and bug, task. A child can't be a higher level than its parent.
	Type      TaskType  `json:"type"`
	UpdatedAt time.Time `json:"updatedAt"`
}

